content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-12-finance-007

=== 用户原始指令 (query.txt) ===
余额数字会变，点进app，能从日历读记账日，还要红色警告

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "余额数字会变，点进app，能从日历读记账日，还要红色警告",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.clock",
        "abilityName": "com.huawei.hmos.clock.phone",
        "uri": ""
      }
    }
  ],
  "dataModelSchema": {
    "finance": {
      "balanceText": {
        "type": "string",
        "description": "当前账户余额数字，运行时可更新，不含币种符号。",
        "sampleValue": "8642"
      },
      "alertText": {
        "type": "string",
        "description": "余额风险或预算超限的红色警告短文案。",
        "sampleValue": "红色警告"
      }
    },
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "日历记账日对应日程的唯一标识。",
              "sampleValue": "calendar-ledger-001"
            },
            "title": {
              "type": "string",
              "description": "日历中的记账日标题。",
              "sampleValue": "记账日"
            },
            "dtStart": {
              "type": "string",
              "description": "记账日开始时间，来自日历日程。",
              "sampleValue": "今天"
            },
            "dtEnd": {
              "type": "string",
              "description": "记账日结束时间，来自日历日程。",
              "sampleValue": "23:59"
            }
          }
        ]
      }
    },
    "asset": {
      "calendarIcon": {
        "type": "string",
        "description": "日历图标资源路径，用于表示记账日来自日历。",
        "sampleValue": "resources/base/media/calendar_fill.svg"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，适合表示从日历读取记账日。黑色 SVG，需放在浅色表面上。",
      "bindTo": "/asset/calendarIcon"
    }
  ]
}

